(async () => {
  await once(v, 'canplaythrough');
  const mark = (s => EVO.push({n: '--- ' + s, tag: '', k: 1, t: performance.now(), rs: v.readyState, ns: v.networkState, ct: cq(v), p: v.paused}));
  const out = {};
  mark('currentTime = 1');
  v.currentTime = 1;
  out.sync = [v.currentTime, v.seeking];
  await once(v, 'seeked');
  await sleep(100);
  out.after1 = S(v);
  mark('currentTime = 99');
  v.currentTime = 99;
  out.sync99 = [v.currentTime, v.seeking];
  await once(v, 'seeked');
  await sleep(100);
  out.after99 = S(v);
  mark('currentTime = -5');
  v.currentTime = -5;
  out.syncNeg = [v.currentTime];
  await once(v, 'seeked');
  await sleep(100);
  out.afterNeg = S(v);
  for (const bad of [NaN, Infinity, -Infinity, 'x', undefined]) {
    try { v.currentTime = bad; out['bad ' + String(bad)] = 'no error ' + v.currentTime; } catch (e) { out['bad ' + String(bad)] = e.name + ': ' + e.message; }
  }
  mark('currentTime = 0.5 then 1.5 then 0.25 at once');
  v.currentTime = 0.5; v.currentTime = 1.5; v.currentTime = 0.25;
  await sleep(500);
  out.rapid = S(v);
  out.ev = evs();
  return out;
})()

