(async () => {
  await once(v, 'loadedmetadata');
  await sleep(100);
  const n = EVO.length;
  const out = {initial: [v.volume, v.muted, v.defaultMuted]};
  v.volume = 0.5; await sleep(50);
  out.v1 = [v.volume, v.muted];
  v.volume = 0.5; await sleep(50);
  v.muted = true; await sleep(50);
  out.v2 = [v.volume, v.muted];
  v.muted = true; await sleep(50);
  v.muted = false; await sleep(50);
  v.volume = 0; await sleep(50);
  out.v3 = [v.volume, v.muted];
  for (const bad of [1.5, -0.1, NaN, Infinity, '0.3', null, undefined]) {
    try { v.volume = bad; out['volume = ' + String(bad)] = 'ok ' + v.volume; } catch (e) { out['volume = ' + String(bad)] = e.name + ': ' + e.message; }
  }
  v.defaultMuted = true; await sleep(50);
  out.defaultMuted = [v.defaultMuted, v.muted, v.hasAttribute('muted')];
  out.ev = evs().slice(n);
  return out;
})()

