(async () => {
  const out = {};
  const a = new Audio('a.mp3');
  watch(a);
  out.sync = [a.preload, a.networkState, a.readyState, a.paused, a.src.replace(location.origin, 'O'), a.isConnected, a.getAttribute('src')];
  await sleep(1200);
  out.s = {rs: a.readyState, ns: a.networkState, dur: a.duration, buf: rng(a.buffered), cs: a.currentSrc.split('/').pop()};
  out.ev = EVO.map(o => o.n + ' rs=' + o.rs);
  out.log = await log();
  const b = new Audio();
  out.empty = [b.src, b.networkState, b.readyState, b.preload, b.controls, b.parentNode];
  b.src = 'a.mp3';
  out.afterSrc = [b.networkState, b.readyState];
  const c = new Audio('nothere.mp3');
  watch(c, 'c', ['error', 'loadstart']);
  await sleep(500);
  out.missing = [c.networkState, c.error && c.error.code];
  return out;
})()

