(async () => {
  await once(v, 'canplaythrough');
  const order = [];
  for (const n of ['play', 'playing', 'pause', 'waiting', 'seeking', 'seeked']) v.addEventListener(n, () => order.push('event ' + n));
  const p1 = v.play().then(() => order.push('promise 1 resolved'), e => order.push('promise 1 ' + e.name));
  const p2 = v.play().then(() => order.push('promise 2 resolved'), e => order.push('promise 2 ' + e.name));
  order.push('same promise? ' + (v.play() === v.play()));
  await sleep(500);
  v.pause();
  await sleep(100);
  return order;
})()

